import osimport ioimport zipfileimport textwrapimport subprocessimport shleximport shutilfrom datetime import datetimefrom flask import Flask, request, send_file, render_template, Response, stream_with_context, jsonifyapp = Flask(__name__)# ==============================================================================# LÓGICA DE INGENIERÍA# ==============================================================================def cidr_to_ip_mask(cidr):    if not cidr: return "0.0.0.0 0.0.0.0"    try:        if '/' not in cidr: return f"{cidr} 255.255.255.255"        ip_addr, mask_len = cidr.split('/')        mask_len = int(mask_len)        mask = (0xffffffff << (32 - mask_len)) & 0xffffffff        mask_str = ".".join(str((mask >> i) & 0xff) for i in [24, 16, 8, 0])        return f"{ip_addr} {mask_str}"    except: return f"{cidr}"def get_pa_crypto_config(profile):    config = {        "DES-SHA256": {"encryption": ["des"], "hash": ["sha256"], "esp_encryption": ["des"], "esp_authentication": ["sha256"]},        "AES128-SHA256": {"encryption": ["aes-128-cbc"], "hash": ["sha256"], "esp_encryption": ["aes-128-cbc"], "esp_authentication": ["sha256"]},        "AES256-SHA256": {"encryption": ["aes-256-cbc"], "hash": ["sha256"], "esp_encryption": ["aes-256-cbc"], "esp_authentication": ["sha256"]},    }    return config.get(profile, config["AES128-SHA256"])def get_fg_crypto_proposal(profile):    config = {        "DES-SHA256": "des-sha256",        "AES128-SHA256": "aes128-sha256",        "AES256-SHA256": "aes256-sha256",    }    return config.get(profile, config["AES128-SHA256"])# ==============================================================================# GENERADORES DE CONTENIDO# ==============================================================================def generate_vars_content(data, pa_crypto):    fg_lan1_ip_mask = cidr_to_ip_mask(data['fg_lan1_cidr'])    fg_lan2_ip_mask = cidr_to_ip_mask(data['fg_lan2_cidr'])    fg_remote_lan1_ip_mask = cidr_to_ip_mask(data['pa_lan1_cidr'])    fg_remote_lan2_ip_mask = cidr_to_ip_mask(data['pa_lan2_cidr'])        psk = data['psk'].replace("'", "").replace('"', "")    tunnel_mask_ip = "255.255.255.255"    pa_tunnel_cidr = "/32"        return f"""    # --- GLOBAL ---    vpn_name: "{data['tunnel_name']}"    vpn_psk: "{psk}"    # --- CRYPTO ---    phase1_proposal: "{get_fg_crypto_proposal(data['crypto_profile'])}"    phase2_proposal: "{get_fg_crypto_proposal(data['crypto_profile'])}"    dh_group: "{data['dh_group']}"    pa_enc_algo: "{pa_crypto['esp_encryption'][0]}"    pa_auth_algo: "{pa_crypto['esp_authentication'][0]}"    # --- FORTIGATE VARS ---    fg_wan_intf: "{data['fg_wan_intf']}"    fg_lan1_intf: "{data['fg_lan1_intf']}"    fg_lan2_intf: "{data['fg_lan2_intf']}"    fg_wan_ip: "{data['fg_wan_ip']}"    fg_vdom: "{data.get('fg_vdom_name', 'root')}"        fg_lan1_cidr_raw: "{data['fg_lan1_cidr']}"    fg_lan2_cidr_raw: "{data['fg_lan2_cidr']}"    fg_lan1_mask: "{fg_lan1_ip_mask}"    fg_lan2_mask: "{fg_lan2_ip_mask}"    fg_remote_lan1_cidr: "{data['pa_lan1_cidr']}"    fg_remote_lan2_cidr: "{data['pa_lan2_cidr']}"    fg_remote_lan1_mask: "{fg_remote_lan1_ip_mask}"    fg_remote_lan2_mask: "{fg_remote_lan2_ip_mask}"    fg_tunnel_ip: "{data['fg_tunnel_ip']} {tunnel_mask_ip}"    fg_remote_tunnel_ip: "{data['pa_remote_tunnel_ip']} {tunnel_mask_ip}"    fg_remote_gw: "{data['pa_remote_wan_ip']}"    # --- PALO ALTO VARS ---    pa_wan_intf: "{data['pa_wan_intf']}"    pa_lan1_intf: "{data['pa_lan1_intf']}"    pa_lan2_intf: "{data['pa_lan2_intf']}"    pa_zone: "{data.get('pa_zone_name', 'VPN_Zone')}"    pa_lan1_cidr: "{data['pa_lan1_cidr']}"    pa_lan2_cidr: "{data['pa_lan2_cidr']}"    pa_remote_lan1_cidr: "{data['fg_lan1_cidr']}"    pa_remote_lan2_cidr: "{data['fg_lan2_cidr']}"    pa_wan_ip: "{data['pa_wan_ip']}"    pa_tunnel_ip: "{data['pa_tunnel_ip']}{pa_tunnel_cidr}"    pa_peer_ip: "{data['fg_remote_wan_ip']}"    pa_nexthop_ip: "{data['fg_remote_tunnel_ip_pa']}"    pa_provider:      ip_address: "{data['pa_mgmt_ip']}"      username: "{data['pa_user']}"      password: "{data['pa_password']}""""def generate_hosts_yml(data):    return f"""all:  children:    fortigates:      hosts:        forti_site_a:          ansible_host: {data['fg_mgmt_ip']}          ansible_user: "{data['fg_user']}"          ansible_password: "{data['fg_password']}"          ansible_connection: httpapi          ansible_network_os: fortinet.fortios.fortios          ansible_httpapi_use_ssl: yes          ansible_httpapi_validate_certs: no          ansible_httpapi_port: 443          ansible_command_timeout: 60          ansible_connect_timeout: 30    paloaltos:      hosts:        palo_site_b:          ansible_host: {data['pa_mgmt_ip']}          ansible_user: "{data['pa_user']}"          ansible_password: "{data['pa_password']}"          ansible_connection: local"""def generate_site_yml_template():    return """---# ==============================================================================# VPN SITE-TO-SITE: FORTIGATE <-> PALO ALTO# Generado automaticamente# ==============================================================================# PLAY 0: PREPARACIÓN DEL ENTORNO- name: Instalar dependencias requeridas para Palo Alto  hosts: localhost  connection: local  gather_facts: no  tasks:    - name: Instalar setuptools      ansible.builtin.command:        cmd: "{{ ansible_playbook_python }} -m pip install --upgrade --quiet setuptools"      changed_when: true        - name: Instalar librerías Palo Alto      ansible.builtin.command:        cmd: "{{ ansible_playbook_python }} -m pip install --quiet pan-python pan-os-python xmltodict requests"      changed_when: true# PLAY 1: FORTIGATE- name: Configurar Overlay FortiGate  hosts: fortigates  connection: httpapi  gather_facts: no  collections:    - fortinet.fortios    vars:__VARS_BLOCK__  tasks:    - name: Configurar VPN Phase 1 (IKE Gateway)      fortios_vpn_ipsec_phase1_interface:        vdom: "{{ fg_vdom }}"        state: "present"        vpn_ipsec_phase1_interface:          name: "{{ vpn_name }}"          interface: "{{ fg_wan_intf }}"           ike_version: "2"          peertype: "any"          net_device: "disable"          proposal: "{{ phase1_proposal }}"          dhgrp: "{{ dh_group }}"          remote_gw: "{{ fg_remote_gw }}"           psksecret: "{{ vpn_psk }}"          nattraversal: "disable"      ignore_errors: yes    - name: Configurar VPN Phase 2 (IPsec SA)      fortios_vpn_ipsec_phase2_interface:        vdom: "{{ fg_vdom }}"        state: "present"        vpn_ipsec_phase2_interface:          name: "{{ vpn_name }}-P2"          phase1name: "{{ vpn_name }}"          proposal: "{{ phase2_proposal }}"          dhgrp: "{{ dh_group }}"          keylifeseconds: 3600          src_subnet: "0.0.0.0 0.0.0.0"           dst_subnet: "0.0.0.0 0.0.0.0"          auto_negotiate: "enable"      ignore_errors: yes    - name: Configurar Interfaz Túnel (VTI)      fortios_system_interface:        vdom: "{{ fg_vdom }}"        state: "present"        system_interface:          name: "{{ vpn_name }}"          vdom: "{{ fg_vdom }}"          type: "tunnel"          interface: "{{ fg_wan_intf }}"          ip: "{{ fg_tunnel_ip }}"          remote_ip: "{{ fg_remote_tunnel_ip }}"          allowaccess: "ping"    # --- OBJETOS DE RED ---    - name: Obj LAN Remota 1      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "REMOTE_LAN1_{{ fg_remote_lan1_cidr | regex_replace('/', '_') }}"            subnet: "{{ fg_remote_lan1_mask }}"     - name: Obj LAN Remota 2      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "REMOTE_LAN2_{{ fg_remote_lan2_cidr | regex_replace('/', '_') }}"            subnet: "{{ fg_remote_lan2_mask }}"     - name: Obj LAN Local 1      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "LOCAL_LAN1_{{ fg_lan1_cidr_raw | regex_replace('/', '_') }}"            subnet: "{{ fg_lan1_mask }}"    - name: Obj LAN Local 2      fortios_firewall_address:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_address:            name: "LOCAL_LAN2_{{ fg_lan2_cidr_raw | regex_replace('/', '_') }}"            subnet: "{{ fg_lan2_mask }}"    # --- ENRUTAMIENTO ESTÁTICO ---    - name: Ruta a Remote LAN 1      fortios_router_static:        vdom: "{{ fg_vdom }}"        state: "present"        router_static:          seq_num: "10"          dst: "{{ fg_remote_lan1_mask }}"                device: "{{ vpn_name }}"    - name: Ruta a Remote LAN 2      fortios_router_static:        vdom: "{{ fg_vdom }}"        state: "present"        router_static:          seq_num: "11"          dst: "{{ fg_remote_lan2_mask }}"          device: "{{ vpn_name }}"    # --- POLÍTICAS DE FIREWALL ---    - name: Politica Salida (LAN -> VPN)      fortios_firewall_policy:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_policy:          policyid: "100"          name: "LAN-to-VPN"          srcintf:            - name: "{{ fg_lan1_intf }}"            - name: "{{ fg_lan2_intf }}"          dstintf:            - name: "{{ vpn_name }}"          srcaddr:             - name: "LOCAL_LAN1_{{ fg_lan1_cidr_raw | regex_replace('/', '_') }}"            - name: "LOCAL_LAN2_{{ fg_lan2_cidr_raw | regex_replace('/', '_') }}"          dstaddr:             - name: "REMOTE_LAN1_{{ fg_remote_lan1_cidr | regex_replace('/', '_') }}"            - name: "REMOTE_LAN2_{{ fg_remote_lan2_cidr | regex_replace('/', '_') }}"          action: "accept"          schedule: "always"          service:             - name: "ALL"          nat: "disable"           logtraffic: "all"    - name: Politica Entrada (VPN -> LAN)      fortios_firewall_policy:        vdom: "{{ fg_vdom }}"        state: "present"        firewall_policy:          policyid: "101"          name: "VPN-to-LAN"          srcintf:            - name: "{{ vpn_name }}"          dstintf:            - name: "{{ fg_lan1_intf }}"            - name: "{{ fg_lan2_intf }}"          srcaddr:             - name: "REMOTE_LAN1_{{ fg_remote_lan1_cidr | regex_replace('/', '_') }}"            - name: "REMOTE_LAN2_{{ fg_remote_lan2_cidr | regex_replace('/', '_') }}"          dstaddr:             - name: "LOCAL_LAN1_{{ fg_lan1_cidr_raw | regex_replace('/', '_') }}"            - name: "LOCAL_LAN2_{{ fg_lan2_cidr_raw | regex_replace('/', '_') }}"          action: "accept"          schedule: "always"          service:             - name: "ALL"          nat: "disable"           logtraffic: "all"# PLAY 2: PALO ALTO- name: Configurar Overlay Palo Alto  hosts: paloaltos  connection: local  gather_facts: no  collections:    - paloaltonetworks.panos    vars:__VARS_BLOCK__  tasks:    - name: Configurar Interfaz Túnel      panos_interface:        provider: "{{ pa_provider }}"        if_name: "tunnel.1"         mode: "layer3"        ip: ["{{ pa_tunnel_ip }}"]        vr_name: "default"        zone_name: "{{ pa_zone }}"        commit: False    - name: Perfil IKE      panos_ike_crypto_profile:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-IKE"        dh_group: ["group{{ dh_group }}"]        encryption: ["{{ pa_enc_algo }}"]        hash: ["{{ pa_auth_algo }}"]        lifetime_seconds: 43200        commit: False    - name: Perfil IPsec      panos_ipsec_profile:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-IPSEC"        dh_group: "group{{ dh_group }}"        esp_encryption: ["{{ pa_enc_algo }}"]        esp_authentication: ["{{ pa_auth_algo }}"]        lifetime_seconds: 3600        commit: False    - name: IKE Gateway      panos_ike_gateway:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}-GW"        version: "ikev2"        interface: "{{ pa_wan_intf }}"            peer_ip: "{{ pa_peer_ip }}"        pre_shared_key: "{{ vpn_psk }}"        ikev2_crypto_profile: "{{ vpn_name }}-IKE"        enable_liveness_check: true        liveness_check_interval: 5        commit: False    - name: IPSec Tunnel      panos_ipsec_tunnel:        provider: "{{ pa_provider }}"        name: "{{ vpn_name }}"        tunnel_interface: "tunnel.1"        ike_gw: "{{ vpn_name }}-GW"        ipsec_profile: "{{ vpn_name }}-IPSEC"        enable_tunneling: true        commit: False    - name: Proxy ID      panos_config_element:        provider: "{{ pa_provider }}"        xpath: "/config/devices/entry[@name='localhost.localdomain']/network/tunnel/ipsec/entry[@name='{{ vpn_name }}']/auto-key/proxy-id"        element: |          <entry name="Wildcard-S2S">            <local>0.0.0.0/0</local>            <remote>0.0.0.0/0</remote>          </entry>        commit: False    - name: Ruta Estática LAN 1 (a FG)      panos_static_route:        provider: "{{ pa_provider }}"        name: "Ruta-a-FG-LAN1"        destination: "{{ pa_remote_lan1_cidr }}"         nexthop_type: "ip-address"        nexthop: "{{ pa_nexthop_ip }}"        interface: "tunnel.1"        virtual_router: "default"        commit: False    - name: Ruta Estática LAN 2 (a FG)      panos_static_route:        provider: "{{ pa_provider }}"        name: "Ruta-a-FG-LAN2"        destination: "{{ pa_remote_lan2_cidr }}"         nexthop_type: "ip-address"        nexthop: "{{ pa_nexthop_ip }}"        interface: "tunnel.1"        virtual_router: "default"        commit: False            - name: Crear Zona VPN si no existe      panos_zone:        provider: "{{ pa_provider }}"        zone: "{{ pa_zone }}"        mode: layer3        interface: ['tunnel.1']        commit: False    - name: Policy Trust-VPN (Salida)      panos_security_rule:        provider: "{{ pa_provider }}"        rule_name: "Permitir_Salida_{{ vpn_name }}"        source_zone: ["trust"]        destination_zone: ["{{ pa_zone }}"]        source_ip: ["any"]        destination_ip: ["{{ pa_remote_lan1_cidr }}", "{{ pa_remote_lan2_cidr }}"]        action: "allow"        commit: False    - name: Policy VPN-Trust (Entrada)      panos_security_rule:        provider: "{{ pa_provider }}"        rule_name: "Permitir_Entrada_{{ vpn_name }}"        source_zone: ["{{ pa_zone }}"]        destination_zone: ["trust"]        source_ip: ["{{ pa_remote_lan1_cidr }}", "{{ pa_remote_lan2_cidr }}"]        destination_ip: ["any"]        action: "allow"        commit: False    - name: COMMIT      paloaltonetworks.panos.panos_commit_firewall:        provider: "{{ pa_provider }}""""def generate_readme():    return """# VPN Site-to-Site Orchestrator## FortiGate <-> Palo Alto### Archivos Generados:- `hosts.yml` - Inventario de dispositivos- `site.yml` - Playbook principal- `ansible.cfg` - Configuración de Ansible### Ejecución:```bashansible-playbook site.yml```### Pre-requisitos:- Ansible 2.9+- Colecciones instaladas:  - fortinet.fortios  - paloaltonetworks.panos### Instalación de colecciones:```bashansible-galaxy collection install fortinet.fortiosansible-galaxy collection install paloaltonetworks.panos```Generado: """ + datetime.now().strftime("%Y-%m-%d %H:%M:%S")# ==============================================================================# VERIFICACIÓN DE CONECTIVIDAD# ==============================================================================def test_connectivity(host, timeout=5):    """Prueba conectividad básica con un host"""    import socket    try:        socket.setdefaulttimeout(timeout)        socket.socket(socket.AF_INET, socket.SOCK_STREAM).connect((host, 443))        return True, "Conectado"    except socket.timeout:        return False, "Timeout"    except socket.error as e:        return False, f"Error: {str(e)}"# ==============================================================================# RUTAS DEL SERVIDOR FLASK# ==============================================================================@app.route('/')def index():    return render_template('frontend.html')@app.route('/test-connectivity', methods=['POST'])def test_devices():    """Verifica conectividad con los dispositivos antes de ejecutar"""    try:        data = request.json        results = {            'fortigate': {},            'paloalto': {}        }                # Test FortiGate        fg_ok, fg_msg = test_connectivity(data['fg_mgmt_ip'])        results['fortigate'] = {'success': fg_ok, 'message': fg_msg, 'ip': data['fg_mgmt_ip']}                # Test Palo Alto        pa_ok, pa_msg = test_connectivity(data['pa_mgmt_ip'])        results['paloalto'] = {'success': pa_ok, 'message': pa_msg, 'ip': data['pa_mgmt_ip']}                return jsonify(results)    except Exception as e:        return jsonify({'error': str(e)}), 500@app.route('/generate', methods=['POST'])def generate_zip():    """Genera y descarga un ZIP con todos los archivos de configuración"""    try:        data = request.json                if "'" in data.get('psk', '') or '"' in data.get('psk', ''):            return jsonify({"error": "Error: La PSK contiene caracteres no permitidos."}), 400                # Generar contenido        pa_crypto_config = get_pa_crypto_config(data['crypto_profile'])        vars_content = generate_vars_content(data, pa_crypto_config)        vars_indented = textwrap.indent(vars_content, '    ')        site_yml_content = generate_site_yml_template().replace('__VARS_BLOCK__', vars_indented)        hosts_yml_content = generate_hosts_yml(data)        ansible_cfg_content = """[defaults]inventory=./hosts.ymlhost_key_checking=Falsetimeout=30deprecation_warnings=False"""        readme_content = generate_readme()                # Crear ZIP en memoria        zip_buffer = io.BytesIO()        with zipfile.ZipFile(zip_buffer, 'w', zipfile.ZIP_DEFLATED) as zip_file:            zip_file.writestr('hosts.yml', hosts_yml_content)            zip_file.writestr('site.yml', site_yml_content)            zip_file.writestr('ansible.cfg', ansible_cfg_content)            zip_file.writestr('README.md', readme_content)                zip_buffer.seek(0)        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")        filename = f"vpn_config_{data['tunnel_name']}_{timestamp}.zip"                return send_file(            zip_buffer,            mimetype='application/zip',            as_attachment=True,            download_name=filename        )    except Exception as e:        return jsonify({'error': str(e)}), 500@app.route('/run', methods=['POST'])def run_playbook():    """Genera los archivos y ejecuta Ansible en streaming."""    try:        data = request.json                if "'" in data.get('psk', '') or '"' in data.get('psk', ''):            return jsonify({"error": "Error: La PSK contiene caracteres no permitidos."}), 400                # Generar contenido        pa_crypto_config = get_pa_crypto_config(data['crypto_profile'])        vars_content = generate_vars_content(data, pa_crypto_config)        vars_indented = textwrap.indent(vars_content, '    ')        site_yml_content = generate_site_yml_template().replace('__VARS_BLOCK__', vars_indented)        hosts_yml_content = generate_hosts_yml(data)        ansible_cfg_content = """[defaults]inventory=./hosts.ymlhost_key_checking=Falsetimeout=30deprecation_warnings=False"""                # Workspace único por sesión        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")        workspace = f"ansible_workspace_{timestamp}"        os.makedirs(workspace, exist_ok=True)                with open(os.path.join(workspace, "hosts.yml"), "w") as f:            f.write(hosts_yml_content)        with open(os.path.join(workspace, "site.yml"), "w") as f:            f.write(site_yml_content)        with open(os.path.join(workspace, "ansible.cfg"), "w") as f:            f.write(ansible_cfg_content)                def generate_log():            try:                cmd = ["ansible-playbook", "site.yml"]                                process = subprocess.Popen(                    cmd,                    cwd=workspace,                    stdout=subprocess.PIPE,                    stderr=subprocess.STDOUT,                    text=True,                    bufsize=1                )                                for line in process.stdout:                    yield line                                process.wait()                                if process.returncode == 0:                    yield "\n[SUCCESS] Ejecución de Ansible finalizada correctamente.\n"                else:                    yield f"\n[ERROR] Ansible finalizó con código de error: {process.returncode}\n"                                # Limpiar workspace después de la ejecución                try:                    shutil.rmtree(workspace)                    yield "[CLEANUP] Workspace temporal eliminado.\n"                except:                    yield "[CLEANUP] No se pudo eliminar el workspace temporal.\n"                                except Exception as e:                yield f"\n[CRITICAL ERROR] No se pudo ejecutar Ansible: {str(e)}\n"                return Response(stream_with_context(generate_log()), mimetype='text/plain')        except Exception as e:        return str(e), 500if __name__ == '__main__':    app.run(host='0.0.0.0', port=5000, debug=True)